+        .filter(n => n.length > 0)
+        .map(n => {
+          const num = parseInt(n);
+          if (num < 0) {
+            // Radix sort implementation doesn't support negative numbers
+            throw new Error("Negative numbers are not supported for this Radix Sort.");
+          }
+          return num;
+        })
+        .filter(n => !isNaN(n) && isFinite(n));
